import 'dart:convert';
import 'package:http/http.dart' as http;

// =============================================================================
// EJERCICIO 1: Comprender la estructura del JSON anidado
// =============================================================================

Future<void> ejercicio1_estructuraJSON() async {
  try {
    final response = await http.get(Uri.parse('https://restcountries.com/v3.1/name/peru'));

    if (response.statusCode == 200) {
      final List<dynamic> data = jsonDecode(response.body);
      final Map<String, dynamic> country = data.first;

      // Imprimimos la estructura completa de forma legible
      print('\n=== ESTRUCTURA JSON PAÍS ===');
      print(JsonEncoder.withIndent('  ').convert(country));

      // Anotamos la estructura de tipos
      print('\n=== TIPOS DE DATOS ===');
      print('''
      country → Map<String, dynamic>
        name → Map<String, dynamic>
          common → String
          official → String
          nativeName → Map<String, Map<String, String>>

        currencies → Map<String, Map<String, String>>
          PEN → Map<String, String>
            name → String
            symbol → String

        capital → List<String>

        languages → Map<String, String>
          spa → String (nombre del idioma)

        flags → Map<String, String>
          png → String (URL)
          svg → String (URL)
      ''');
    } else {
      print('Error: ${response.statusCode}');
      print('Body: ${response.body}');
    }
  } catch (e) {
    print('Error al realizar la petición: $e');
  }
}

void main() async {
  // Ejercicio 1: Estructura del JSON
  print('\n=== EJERCICIO 1: ESTRUCTURA JSON ===');
  await ejercicio1_estructuraJSON();
}
